from pathlib import Path

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
BASE = len(ALPHABET)
PREFIX = "ORD-"
WIDTH = 4


def base36_to_int(s: str) -> int:
    value = 0
    for ch in s:
        try:
            digit = ALPHABET.index(ch)
        except ValueError as exc:
            raise ValueError(f"Invalid base36 character: {ch}") from exc
        value = value * BASE + digit
    return value


def int_to_base36(n: int, width: int) -> str:
    if n < 0:
        raise ValueError("Value must be non-negative")
    chars = []
    for _ in range(width):
        n, rem = divmod(n, BASE)
        chars.append(ALPHABET[rem])
    if n != 0:
        raise ValueError("Next ID exceeds 4-character range")
    return "".join(reversed(chars))


def next_order_id(ids_path: Path) -> str:
    lines = [line.strip() for line in ids_path.read_text(encoding="utf-8").splitlines()]
    ids = [line for line in lines if line]
    if not ids:
        next_suffix = int_to_base36(0, WIDTH)
        return f"{PREFIX}{next_suffix}"

    last_id = ids[-1]
    if not last_id.startswith(PREFIX):
        raise ValueError(f"Invalid ID format: {last_id}")

    suffix = last_id[len(PREFIX):]
    if len(suffix) != WIDTH:
        raise ValueError(f"Invalid ID width in: {last_id}")

    next_value = base36_to_int(suffix) + 1
    next_suffix = int_to_base36(next_value, WIDTH)
    return f"{PREFIX}{next_suffix}"


if __name__ == "__main__":
    ids_file = Path("ids.txt")
    print(next_order_id(ids_file))
