from pathlib import Path

PREFIX = "ORD-"
WIDTH = 4
ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
BASE = len(ALPHABET)


def decode_base36(value: str) -> int:
    n = 0
    for ch in value:
        if ch not in ALPHABET:
            raise ValueError(f"Invalid base36 character: {ch!r}")
        n = n * BASE + ALPHABET.index(ch)
    return n


def encode_base36(number: int, width: int) -> str:
    if number < 0:
        raise ValueError("number must be non-negative")

    chars = []
    while number:
        number, rem = divmod(number, BASE)
        chars.append(ALPHABET[rem])

    encoded = "".join(reversed(chars)) or "0"
    if len(encoded) > width:
        raise ValueError("next id exceeds supported width")
    return encoded.rjust(width, "0")


def next_order_id(path: Path) -> str:
    lines = path.read_text(encoding="utf-8").splitlines()
    issued = [line.strip() for line in lines if line.strip()]

    if not issued:
        return PREFIX + ("0" * WIDTH)

    last_id = issued[-1]
    if not last_id.startswith(PREFIX):
        raise ValueError(f"Invalid id format: {last_id!r}")

    suffix = last_id[len(PREFIX):]
    if len(suffix) != WIDTH:
        raise ValueError(f"Invalid id width: {last_id!r}")

    next_value = decode_base36(suffix) + 1
    return PREFIX + encode_base36(next_value, WIDTH)


if __name__ == "__main__":
    ids_path = Path("ids.txt")
    print(next_order_id(ids_path))
