from pathlib import Path

PREFIX = "ORD-"
WIDTH = 4
ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
BASE = len(ALPHABET)


def to_int(code: str) -> int:
    value = 0
    for ch in code:
        value = value * BASE + ALPHABET.index(ch)
    return value


def to_code(value: int) -> str:
    chars = []
    for _ in range(WIDTH):
        value, rem = divmod(value, BASE)
        chars.append(ALPHABET[rem])
    if value != 0:
        raise ValueError("next id exceeds 4-character capacity")
    return "".join(reversed(chars))


def main() -> None:
    lines = [line.strip() for line in Path("ids.txt").read_text().splitlines() if line.strip()]
    if not lines:
        raise ValueError("ids.txt has no ids")

    latest = lines[-1]
    if not latest.startswith(PREFIX) or len(latest) != len(PREFIX) + WIDTH:
        raise ValueError(f"invalid id format: {latest}")

    current_value = to_int(latest[len(PREFIX):])
    next_id = PREFIX + to_code(current_value + 1)
    print(next_id)


if __name__ == "__main__":
    main()
